    },
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "54 series insufficient to detect a unique effect of adherence on series win/loss; game-level expansion introduces many confounders without sufficient statistical power for a rare outcome."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "Suppression-conditional mix definitions may be noisy, reducing power and amplifying RTM_SELECTION."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "Defining adherence thresholds, suppression states, and multiple play-type aggregates creates a large multiplicity problem."
    },
    {
      "code": "RTM_SELECTION",
      "text": "Teams with high adherence may be those that are already performing well, leading to regression-to-the-mean artifacts when predicting future winning."
    }
  ],
  "predicted_outcome": {
    "supported": 0.05,
    "rejected": 0.2,
    "untestable": 0.25,
    "artifact": 0.4,
    "uncertain": 0.1
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "The marginal predictive effect of adherence to a suppression-conditional recommended play-type mix on game win/loss, net of pre-game win probability and team strength.",
    "unit": "game (regular season and playoffs)",
    "sample": "All NBA games from 2022-23 through 2025-26 where a suppression-conditional recommended mix can be computed and adherence measured; expected >3000 games.",
